-- شغّل السكريبت ده مرة واحدة بس من Supabase SQL Editor.
-- بيعمل جدول religious_collections (الأذكار وقوائم الأدعية) وجدول
-- sadaqah_jariyah (الصدقة الجارية)، وبيزرعهم بنفس المحتوى الموجود بالظبط
-- في الكود دلوقتي (اتسحب تلقائيًا من azkar_data.dart ومن memorial_screen.dart،
-- مش معاد كتابته يدوي، فمفيش فرق ولا خطأ نسخ).

-- ============================================================
-- 1) جدول religious_collections (الأذكار + قوائم الأدعية)
-- ============================================================
create table if not exists public.religious_collections (
  id bigint generated always as identity primary key,
  kind text not null check (kind in ('azkar_category', 'dua_list')),
  slug text unique, -- مطلوب لـ dua_list بس (عشان التطبيق يلاقيها)، مش مهم لـ azkar_category
  title text not null,
  icon text, -- اسم أيقونة نصي، لفئات الأذكار بس (wb_sunny/nights_stay/mosque/bedtime)
  items jsonb not null, -- [{"text": "...", "count": 1, "note": null}, ...]
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);

alter table public.religious_collections enable row level security;

-- القراءة مفتوحة للجميع (زي achievements_catalog) عشان التطبيق يعرض المحتوى
-- من غير تسجيل دخول لازم. الكتابة اقصرها على نفس دور الأدمن اللي بتستخدموه
-- فعليًا في باقي جداول اللوحة (راجعوا الـ policy الموجودة عندكم على
-- achievements_catalog وكرروها بنفس الشكل هنا، مقدرتش أتأكد من اسم الدور
-- بالظبط من غير ما أشوف قاعدة بياناتكم الفعلية)
create policy "anyone can read religious_collections" on public.religious_collections
  for select using (true);

