  ('dua_list', 'dua_study', 'أدعية للمذاكرة والامتحانات', '[{"text": "رَبِّ زِدْنِي عِلْمًا", "count": 1, "note": null}, {"text": "رَبِّ اشْرَحْ لِي صَدْرِي، وَيَسِّرْ لِي أَمْرِي، وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي", "count": 1, "note": null}, {"text": "اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا", "count": 1, "note": null}, {"text": "اللَّهُمَّ إِنِّي أَسْأَلُكَ فَهْمَ النَّبِيِّينَ، وَحِفْظَ الْمُرْسَلِينَ، وَإِلْهَامَ الْمَلَائِكَةِ الْمُقَرَّبِينَ", "count": 1, "note": null}, {"text": "اللَّهُمَّ أَخْرِجْنِي مِنْ ظُلُمَاتِ الْوَهْمِ، وَأَكْرِمْنِي بِنُورِ الْفَهْمِ", "count": 1, "note": null}, {"text": "اللَّهُمَّ افْتَحْ عَلَيَّ فَتْحَ الْعَارِفِينَ بِكَ، وَافْهَمْنِي فَهْمَ الْمُوَحِّدِينَ لَكَ", "count": 1, "note": null}, {"text": "اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَقَلْبًا خَاشِعًا، وَيَقِينًا صَادِقًا", "count": 1, "note": null}, {"text": "رَبِّ لَا تَذَرْنِي فَرْدًا وَأَنْتَ خَيْرُ الْوَارِثِينَ", "count": 1, "note": "دعاء للثبات والتوفيق"}, {"text": "اللَّهُمَّ اجْعَلْ هَذَا الْمَجْهُودَ خَالِصًا لِوَجْهِكَ الْكَرِيمِ، وَبَارِكْ لِي فِي وَقْتِي", "count": 1, "note": null}, {"text": "حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ", "count": 1, "note": "قبل الامتحان"}]'::jsonb, 1);
insert into public.religious_collections (kind, slug, title, items, sort_order) values
  ('dua_list', 'dua_repentance', 'أدعية التوبة والاستغفار', '[{"text": "أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ", "count": 1, "note": null}, {"text": "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ", "count": 1, "note": "سيد الاستغفار"}, {"text": "رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ", "count": 1, "note": null}, {"text": "اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي", "count": 1, "note": null}, {"text": "رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ", "count": 1, "note": null}, {"text": "اللَّهُمَّ اغْفِرْ لِي خَطِيئَتِي وَجَهْلِي، وَإِسْرَافِي فِي أَمْرِي، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي", "count": 1, "note": null}, {"text": "يَا مُقَلِّبَ الْقُلُوبِ وَالْأَبْصَارِ، يَا هَادِيَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ", "count": 1, "note": null}, {"text": "اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي", "count": 1, "note": null}]'::jsonb, 2);
