  ('dua_list', 'dua_general', 'أدعية عامة', '[{"text": "اللَّهُمَّ اشْفِ كُلَّ مَرِيضٍ، وَارْحَمْ كُلَّ مَيِّتٍ مِنَ الْمُسْلِمِينَ", "count": 1, "note": null}, {"text": "اللَّهُمَّ اغْفِرْ لِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ، الْأَحْيَاءِ مِنْهُمْ وَالْأَمْوَاتِ", "count": 1, "note": null}, {"text": "اللَّهُمَّ اجْعَلْ خَيْرَ عُمُرِي آخِرَهُ، وَخَيْرَ عَمَلِي خَوَاتِمَهُ، وَخَيْرَ أَيَّامِي يَوْمَ أَلْقَاكَ فِيهِ", "count": 1, "note": null}, {"text": "رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَى وَالِدَيَّ", "count": 1, "note": null}, {"text": "اللَّهُمَّ اجْبُرْ كَسْرَ كُلِّ قَلْبٍ حَزِينٍ، وَفَرِّجْ هَمَّ كُلِّ مَهْمُومٍ", "count": 1, "note": null}, {"text": "اللَّهُمَّ بَارِكْ لَنَا فِيمَا رَزَقْتَنَا، وَقِنَا عَذَابَ النَّارِ", "count": 1, "note": null}]'::jsonb, 3);

-- ============================================================
-- 2) جدول sadaqah_jariyah
-- ============================================================
create table if not exists public.sadaqah_jariyah (
  id bigint generated always as identity primary key,
  title text not null default 'صدقة جارية',
  name text not null,
  body text not null,
  date text, -- نص حر زي '23 / 5 / 2023'، مش لازم يكون تاريخ SQL حقيقي
  dua_request text not null,
  image_url text, -- رابط صورة (Supabase Storage أو أي رابط https) — اختياري
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);

alter table public.sadaqah_jariyah enable row level security;
create policy "anyone can read sadaqah_jariyah" on public.sadaqah_jariyah
  for select using (true);

-- بذرة المحتوى الحالي — الصور مش متزرعة هنا (كانت assets جوه التطبيق نفسه
-- مش روابط)، سيبوا image_url فاضي للصفين دول لحد ما ترفعوا صورهم الحقيقية
-- على Supabase Storage وتحطوا الرابط من اللوحة
insert into public.sadaqah_jariyah (title, name, body, date, dua_request, sort_order) values
  ('صدقة جارية', 'محمد إمام', 'أقل ما يقال عنه إنه كان طالب علم حقيقي، كان بيسعى وحلمه يدخل ثانوية عامة، بس توفي قبل ما يحقق حلمه.

وحبيت أعمله صدقة جارية ليه، فجت فكرة "طالب علم".

متنسوش تدعوله 💔', '23 / 5 / 2023', 'ادعِ له بالرحمة والمغفرة 🤍', 0);
insert into public.sadaqah_jariyah (title, name, body, date, dua_request, sort_order) values
  ('صدقة جارية', 'أشرف سعد', 'يرحل الإنسان ويبقى الأثر
والرحيل رحلةٌ إلى الحياة

